"""Save latent representation Z generated by the trained model."""
import numpy as np
import torch
from load_data import Data
from auxiliary_functions import save_z

device=torch.device("cuda"if torch.cuda.is_available() else "cpu")

weight_path = '../c_torch_weight'
result_path= '../d_results_of_z'

n_samples = 10  # sampling numbers
x_input = torch.from_numpy(Data[:, np.newaxis, :, :, :])
x_input = x_input.to(device)
x_input = x_input.to(torch.float32)

z_list,z_specific_list=[], [] # feature of all patients, size:2898*32

"Load CVAE model"
CVAE_model=torch.load(weight_path + '/model_best_train.pth',map_location=device,weights_only=False)   # load model weight

for i in range(n_samples):
    print(i,"-th epoch of CVAE")
    mu,log_var=CVAE_model._encoder(x_input)    #reconstruct Z
    mu_specific,log_var_specific=CVAE_model.encoder_specific(x_input)

    z=CVAE_model._sampling(mu=mu,log_var=log_var)
    z_specific=CVAE_model._sampling(mu=mu_specific,log_var=log_var_specific)

    z_list.append(z)
    z_specific_list.append(z_specific)

"Save features"
z_tensor=torch.stack(z_list,dim=0)
z_specific_tensor=torch.stack(z_specific_list,dim=0)

Z=z_tensor.detach().cpu().numpy()
Z_specific=z_specific_tensor.detach().cpu().numpy()

# save features as npz,size:n_samples*2898*32
save_z(result_path,Z,Z_specific)
